'use client';

import * as React from 'react';
import './glyph.css';

/* GLYPH: a static icon at a size (10 tiny, 14 small, 16 regular) in an ink (ink, ink2, ink3, or inherit from
 * the words it sits in).
 * It is decorative (aria-hidden) and draws nothing itself: the icon inside inherits the ink. */

export interface GlyphProps extends React.HTMLAttributes<HTMLSpanElement> {
  size?: 'tiny' | 'small' | 'regular';
  tone?: 'ink' | 'ink2' | 'ink3' | 'inherit';
}

export function Glyph({ size = 'small', tone = 'ink2', className, ...props }: GlyphProps) {
  return <span aria-hidden data-size={size} data-tone={tone} className={className ? `mu-glyph ${className}` : 'mu-glyph'} {...props} />;
}

@import "../tokens.css";

/* Glyph: a static icon at a size in an ink. Its values are the glyph recipe (--mu-r-glyph-*). */
.mu-glyph { display: inline-grid; place-items: center; flex: none; }
/* tone="inherit": the words' own ink (an engraving's glyph). */
.mu-glyph[data-tone="ink"] { color: var(--mu-r-glyph-ink-ink); }
.mu-glyph[data-tone="ink2"] { color: var(--mu-r-glyph-ink-ink2); }
.mu-glyph[data-tone="ink3"] { color: var(--mu-r-glyph-ink-ink3); }
.mu-glyph[data-size="tiny"] > svg { width: var(--mu-r-glyph-size-tiny); height: var(--mu-r-glyph-size-tiny); }
.mu-glyph[data-size="small"] > svg { width: var(--mu-r-glyph-size-small); height: var(--mu-r-glyph-size-small); }
.mu-glyph[data-size="regular"] > svg { width: var(--mu-r-glyph-size-regular); height: var(--mu-r-glyph-size-regular); }
